[{"order":1,"type":"heading","text":"Testing Strategies and Mocking in GraphQL"},{"order":2,"type":"paragraph","text":"Testing GraphQL APIs requires a different mindset compared to REST endpoints. Because GraphQL allows clients to request arbitrary shapes of data through a single endpoint, traditional HTTP status code checks and endpoint-by-endpoint tests are insufficient. A robust testing strategy must cover schema validation, resolver logic, and end-to-end integration."},{"order":3,"type":"subheading","text":"1. Unit Testing Resolvers"},{"order":4,"type":"paragraph","text":"Resolvers are the backbone of a GraphQL server. Since they are pure JavaScript or TypeScript functions taking parameters like (parent, args, context, info), unit testing them is straightforward. You can mock the context and data sources to test business logic in isolation."},{"order":5,"type":"code","text":"const userResolver = require('./resolvers/user');

test('should fetch user by id', async () => {
  const mockContext = {
    dataSources: {
      userAPI: {
        getUserById: jest.fn().mockResolvedValue({ id: '1', name: 'Alice' })
      }
    }
  };

  const result = await userResolver.Query.user(null, { id: '1' }, mockContext);
  expect(result).toEqual({ id: '1', name: 'Alice' });
});"},{"order":6,"type":"subheading","text":"2. Schema Mocking for Rapid Prototyping"},{"order":7,"type":"paragraph","text":"GraphQL supports schema-first development, allowing you to mock entire schemas instantly using libraries like @graphql-tools/mock. This enables frontend teams to develop against a fully functional API before backend resolvers are even written."},{"order":8,"type":"code","text":"const { addMocksToSchema } = require('@graphql-tools/mock');
const { makeExecutableSchema } = require('@graphql-tools/schema');
const { graphql } = require('graphql');

const typeDefs = `
  type User {
    id: ID!
    name: String!
    age: Int!
  }
  type Query {
    user(id: ID!): User
  }
`;

const schema = makeExecutableSchema({ typeDefs });
const schemaWithMocks = addMocksToSchema({ schema });

graphql({
  schema: schemaWithMocks,
  source: '{ user(id: "1") { id name age } }'
}).then((result) => {
  console.log(JSON.stringify(result, null, 2));
});"},{"order":9,"type":"subheading","text":"3. Integration and End-to-End (E2E) Testing"},{"order":10,"type":"paragraph","text":"Integration tests ensure that your schema, resolvers, and data sources work together cohesively. Instead of mocking individual resolvers, you spin up a test instance of your GraphQL server and execute real queries against it."},{"order":11,"bullet_point":"Always test both successful queries and expected error payloads."},{"order":12,"bullet_point":"Verify that mutations correctly modify underlying database states."},{"order":13,"bullet_point":"Ensure authorization rules and directives reject unauthorized operations."},{"order":14,"type":"subheading","text":"Summary"},{"order":15,"paragraph":"By combining unit tests for complex resolvers, schema mocks for UI development, and integration tests for end-to-end execution, you ensure high availability, predictability, and safety in your GraphQL services."}]
